import os, json, openpyxl
print('cwd', os.getcwd())
print('files', os.listdir('.'))
for base in ['inputs','/mnt/data','data']:
    if os.path.isdir(base):
        print(base, os.listdir(base)[:20])
mp='inputs/manifest.json'
if os.path.exists(mp):
    print(open(mp).read()[:1500])

import openpyxl, json
wb = openpyxl.load_workbook('inputs/sources/fil_01M6G9M0BMBR24WYVDJY6F7N0W.xlsx', data_only=False)
wbv = openpyxl.load_workbook('inputs/sources/fil_01M6G9M0BMBR24WYVDJY6F7N0W.xlsx', data_only=True)
for name in wb.sheetnames:
    ws = wb[name]; wsv = wbv[name]
    print('==', name, ws.dimensions)
    for r in range(1, min(ws.max_row, 14)+1):
        row=[]
        for c in range(1, ws.max_column+1):
            f = ws.cell(r,c).value
            v = wsv.cell(r,c).value
            if isinstance(f,str) and f.startswith('='):
                row.append(f'{ws.cell(r,c).coordinate}={f!r}->{v!r}')
            else:
                row.append(f'{ws.cell(r,c).coordinate}:{f!r}')
        print(' | '.join(row))

